try: refund_shipping(p(), "100.01", T0)
except BillingError as e: print("over:", e.code)

# non-positive
for a in ("0", "-1"):
    try: refund_shipping(p(), a, T0)
    except BillingError as e: print("nonpos:", e.code)

# approval
try: refund_shipping(p("1000.00"), "500.01", T0)
except BillingError as e: print("approval:", e.code)
refund_shipping(p("1000.00"), "500.00", T0); print("500 ok")

# idempotency
y=p(); refund_shipping(y,"10.00",T0,idempotency_key="k1"); refund_shipping(y,"10.00",T0,idempotency_key="k1")
